<file path="src/reports.js">
import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get all overdue invoices (issued or partially_paid with dueDate before asOf).
 * @param {Array<object>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get a summary of VAT by rate for invoices with status issued, partially_paid, or paid.
 * @param {Array<object>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    for (const line of invoice.lines) {
      const vatRate = line.vatRate ?? 0;
      const total = line.qty * line.unitPrice;
      const discount = lineDiscount(line);
      const base = total - discount;
      const vat = lineVAT(line);

      if (!vatMap.has(vatRate)) {
        vatMap.set(vatRate, { rate: vatRate, base: 0, vat: 0 });
      }

      const entry = vatMap.get(vatRate);
      entry.base += base;
      entry.vat += vat;
    }
  }

  return Array.from(vatMap.values()).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an overdue invoice: 0.04% per day of the amount still due.
 * @param {object} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;
  return roundCents(fee);
}
